SELECT 
FROM sre_rca_evaluation_suite_version
WHERE suite_id = #{suiteId}
  AND manifest_sha256 = #{manifestSha256}
LIMIT 1

SELECT MAX(version_no)
FROM sre_rca_evaluation_suite_version
WHERE suite_id = #{suiteId}

SELECT 
FROM sre_rca_evaluation_suite_version
WHERE suite_id = #{suiteId}
ORDER BY version_no DESC, id DESC
LIMIT #{limit}
